  $('#closeWorldInspector').onclick=()=>{this.selected=null;this.inspect()};target.querySelectorAll('[data-select-relation]').forEach(el=>el.onclick=()=>{this.selected={kind:'relationship',id:el.dataset.selectRelation};this.inspect()});
